//! Extracted objects routes (`docs/specs/pictures.md`, task P3.6).
//!
//! | Method | Path | Response |
//! |---|---|---|
//! | GET | `/sessions/{id}/objects/stats?kind` | [`ObjectStats`] |
//! | GET | `/sessions/{id}/objects?limit&cursor&sort&order&kind&type&host&q&min_size&max_size` | `Page<ObjectItem>` |
//! | GET | `/sessions/{id}/objects/{sha256}` | the original file (download) |
//! | GET | `/sessions/{id}/objects/{sha256}/thumb` | PNG thumbnail generated by NetSift |
//! | GET | `/sessions/{id}/objects/{sha256}/preview` | larger PNG rendition (viewer) |
//!
//! Like the other analysis routes, they answer 409 while the session is importing or failed.
//! The webview only ever displays PNG files **re-encoded by NetSift** (`thumb`, `preview`:
//! decoded pixels, nothing else of the original survives). The original is always an
//! attachment typed `application/octet-stream`, with `Content-Security-Policy: sandbox` and
//! `nosniff`, whatever its content (SVG, HTML disguised as an image...). Unknown or malformed
//! digests give 404 (never a path: the file name derives from a validated digest); a blob that
//! does not have its recorded size gives 409.

use std::sync::Arc;

use axum::extract::{Path as UrlPath, State};
use axum::http::{HeaderValue, header};
use axum::response::{IntoResponse, Response};
use axum::routing::get;
use axum::{Json, Router};
use netsift_engine::thumbs::{self, PREVIEW_SIZE, THUMB_SIZE};
use netsift_store::objects::{self as store, ObjectFilter, ObjectRow, ObjectSort, thumb};
use netsift_store::{PageRequest, Session};
use serde::{Deserialize, Serialize};
use ts_rs::TS;

use crate::contract::Page;
use crate::convert::us;
use crate::extract::ApiQuery;
use crate::overview::open_ready;
use crate::sessions::{DEFAULT_LIMIT, MAX_LIMIT, parse_id};
use crate::{ApiError, AppState, blocking};

/// Hosts listed by the statistics (filter options).
const TOP_HOSTS: u32 = 50;
/// Longest accepted search or filter text.
const MAX_QUERY_LEN: usize = 256;
/// Largest stored thumbnail served (they are at most 320 px wide, a few dozen KiB).
const MAX_THUMB_FILE: u64 = 4 * 1024 * 1024;

pub(crate) fn routes() -> Router<Arc<AppState>> {
    Router::new()
        .route("/sessions/{id}/objects", get(list))
        .route("/sessions/{id}/objects/stats", get(stats))
        .route("/sessions/{id}/objects/{sha256}", get(download))
        .route("/sessions/{id}/objects/{sha256}/thumb", get(thumbnail))
        .route("/sessions/{id}/objects/{sha256}/preview", get(preview))
}

// ------------------------------------------------------------------------------------------
// DTOs
// ------------------------------------------------------------------------------------------

/// Objects of one detected type.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[ts(export)]
pub struct ObjectTypeCount {
    pub mime: String,
    pub count: u64,
}

/// Objects served by one host.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[ts(export)]
pub struct ObjectHostCount {
    pub host: String,
    pub count: u64,
}

/// `GET /sessions/{id}/objects/stats`: figures and filter options of the Pictures view.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[ts(export)]
pub struct ObjectStats {
    /// Distinct objects (deduplicated by SHA-256).
    pub count: u64,
    /// Their total size, in bytes.
    pub bytes: u64,
    /// Transactions that carried them.
    pub occurrences: u64,
    /// Per detected type, most frequent first.
    pub types: Vec<ObjectTypeCount>,
    /// Top 50 hosts, most frequent first.
    pub hosts: Vec<ObjectHostCount>,
}

/// One extracted object (first transaction that carried it).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, TS)]
#[ts(export)]
pub struct ObjectItem {
    /// Lower-case hex SHA-256 (key of the file routes).
    pub sha256: String,
    pub size: u64,
    /// Type detected from the content (magic number).
    pub mime: String,
    /// `Content-Type` announced by the server.
    pub declared_type: Option<String>,
    /// Dimensions, once decoded.
    pub width: Option<u32>,
    pub height: Option<u32>,
    /// `ready` or `pending`: a thumbnail can be fetched; `none` (SVG, never rasterized) or
    /// `failed` (not decodable): no thumbnail.
    pub thumb: String,
    pub occurrences: u64,
    pub first_ts_us: i64,
    pub last_ts_us: i64,
    /// Flow id of the first transaction (string: may exceed 2^53).
    pub flow_id: String,
    pub client_ip: String,
    pub server_ip: String,
    pub server_port: u16,
    pub host: Option<String>,
    /// Request target as sent.
    pub uri: Option<String>,
    /// `http://host/target` when it can be rebuilt (text only, never fetched).
    pub url: Option<String>,
    /// Name of the downloaded file.
    pub file_name: String,
}

// ------------------------------------------------------------------------------------------
// Conversions
// ------------------------------------------------------------------------------------------

/// Extension of a detected type.
fn extension(mime: &str) -> &'static str {
    match mime {
        "image/png" => "png",
        "image/jpeg" => "jpg",
        "image/gif" => "gif",
        "image/webp" => "webp",
        "image/bmp" => "bmp",
        "image/x-icon" => "ico",
        "image/svg+xml" => "svg",
        _ => "bin",
    }
}

/// File name of a downloaded object: last segment of the URL path (letters, digits, `.-_`
/// only, without its extension), the first 12 hex digits of the digest, and the extension of
/// the detected type (never the announced one).
fn file_name(row: &ObjectRow) -> String {
    let segment = row
        .uri
        .as_deref()
        .unwrap_or_default()
        .split(['?', '#'])
        .next()
        .unwrap_or_default()
        .rsplit('/')
        .next()
        .unwrap_or_default();
    let segment = segment.rsplit_once('.').map_or(segment, |(stem, _)| stem);
    let stem: String = segment
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || matches!(c, '-' | '_') {
                c
            } else {
                '_'
            }
        })
        .take(64)
        .collect();
    let stem = stem.trim_matches('_');
    let stem = if stem.is_empty() { "object" } else { stem };
    let short = row.sha256.get(..12).unwrap_or_default();
    format!("{stem}-{short}.{}", extension(&row.mime))
}

fn url(row: &ObjectRow) -> Option<String> {
    let uri = row.uri.as_deref()?;
    if uri.contains("://") {
        return Some(uri.to_owned());
    }
    let host = row.host.as_deref()?;
    uri.starts_with('/').then(|| format!("http://{host}{uri}"))
}

fn item(row: ObjectRow) -> ObjectItem {
    ObjectItem {
        file_name: file_name(&row),
        url: url(&row),
        sha256: row.sha256,
        size: row.size,
        mime: row.mime,
        declared_type: row.declared_type,
        width: row.width,
        height: row.height,
        thumb: row.thumb,
        occurrences: row.occurrences,
        first_ts_us: us(row.first_ts),
        last_ts_us: us(row.last_ts),
        flow_id: row.flow_id.to_string(),
        client_ip: row.client_ip,
        server_ip: row.server_ip,
        server_port: row.server_port,
        host: row.host,
        uri: row.uri,
    }
}

// ------------------------------------------------------------------------------------------
// Handlers
// ------------------------------------------------------------------------------------------

/// Which objects a request concerns: the images (Pictures view, default) or all.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
enum Kind {
    #[default]
    Image,
    All,
}

#[derive(Debug, Default, Deserialize)]
struct StatsQuery {
    #[serde(default)]
    kind: Kind,
}

async fn stats(
    State(state): State<Arc<AppState>>,
    UrlPath(id): UrlPath<String>,
    ApiQuery(query): ApiQuery<StatsQuery>,
) -> Result<Json<ObjectStats>, ApiError> {
    let id = parse_id(&id)?;
    blocking(&state, move |s| {
        let (_, session) = open_ready(s, &id)?;
        let st = store::stats(session.conn(), query.kind == Kind::Image, TOP_HOSTS)?;
        Ok(ObjectStats {
            count: st.count,
            bytes: st.bytes,
            occurrences: st.occurrences,
            types: st
                .types
                .into_iter()
                .map(|(mime, count)| ObjectTypeCount { mime, count })
                .collect(),
            hosts: st
                .hosts
                .into_iter()
                .map(|(host, count)| ObjectHostCount { host, count })
                .collect(),
        })
    })
    .await
    .map(Json)
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
enum Sort {
    #[default]
    Time,
    Size,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "lowercase")]
enum Order {
    #[default]
    Asc,
    Desc,
}

#[derive(Debug, Default, Deserialize)]
struct ListQuery {
    limit: Option<u32>,
    cursor: Option<String>,
    /// `time` (order of first appearance, default) or `size`.
    #[serde(default)]
    sort: Sort,
    #[serde(default)]
    order: Order,
    #[serde(default)]
    kind: Kind,
    /// Exact detected type (`image/png`).
    #[serde(rename = "type")]
    mime: Option<String>,
    /// Exact host.
    host: Option<String>,
    /// Text in the host or the request target.
    q: Option<String>,
    min_size: Option<u64>,
    max_size: Option<u64>,
}

fn text(name: &str, v: Option<String>) -> Result<Option<String>, ApiError> {
    match v {
        Some(v) if v.len() > MAX_QUERY_LEN => {
            Err(ApiError::BadRequest(format!("{name}: too long")))
        }
        v => Ok(v.filter(|v| !v.trim().is_empty())),
    }
}

async fn list(
    State(state): State<Arc<AppState>>,
    UrlPath(id): UrlPath<String>,
    ApiQuery(query): ApiQuery<ListQuery>,
) -> Result<Json<Page<ObjectItem>>, ApiError> {
    let id = parse_id(&id)?;
    blocking(&state, move |s| {
        let (_, session) = open_ready(s, &id)?;
        let filter = ObjectFilter {
            images_only: query.kind == Kind::Image,
            mime: text("type", query.mime)?,
            host: text("host", query.host)?,
            q: text("q", query.q)?,
            min_size: query.min_size,
            max_size: query.max_size,
        };
        let request = PageRequest {
            limit: match query.limit {
                None | Some(0) => DEFAULT_LIMIT,
                Some(n) => n.min(MAX_LIMIT),
            },
            cursor: query.cursor,
        };
        let sort = match query.sort {
            Sort::Time => ObjectSort::Time,
            Sort::Size => ObjectSort::Size,
        };
        let conn = session.conn();
        let page = store::objects_page(conn, &filter, sort, query.order == Order::Desc, &request)?;
        Ok(Page {
            items: page.items.into_iter().map(item).collect(),
            next_cursor: page.next_cursor,
            total_estimate: Some(store::count_objects(conn, &filter)?),
        })
    })
    .await
    .map(Json)
}

/// An object row, 404 for an unknown or malformed digest.
fn find(session: &Session, sha256: &str) -> Result<ObjectRow, ApiError> {
    netsift_store::session::blob_relpath(sha256).ok_or(ApiError::NotFound)?;
    store::object(session.conn(), sha256)?.ok_or(ApiError::NotFound)
}

/// The original bytes of an object, checked against the recorded size.
fn read_original(session: &Session, row: &ObjectRow) -> Result<Vec<u8>, ApiError> {
    let path = session.blob_path(&row.sha256).ok_or(ApiError::NotFound)?;
    let bytes = std::fs::read(&path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            ApiError::NotFound
        } else {
            tracing::error!("cannot read an object blob: {e}");
            ApiError::Internal
        }
    })?;
    if u64::try_from(bytes.len()).ok() != Some(row.size) {
        tracing::warn!("an object blob does not have its recorded size");
        return Err(ApiError::Conflict(
            "the stored object file is incomplete".to_owned(),
        ));
    }
    Ok(bytes)
}

fn secure(res: &mut Response) {
    let headers = res.headers_mut();
    headers.insert(
        header::CONTENT_SECURITY_POLICY,
        HeaderValue::from_static("sandbox"),
    );
    headers.insert(
        header::X_CONTENT_TYPE_OPTIONS,
        HeaderValue::from_static("nosniff"),
    );
    headers.insert(header::CACHE_CONTROL, HeaderValue::from_static("no-store"));
}

async fn download(
    State(state): State<Arc<AppState>>,
    UrlPath((id, sha256)): UrlPath<(String, String)>,
) -> Result<Response, ApiError> {
    let id = parse_id(&id)?;
    let (row, bytes) = blocking(&state, move |s| {
        let (_, session) = open_ready(s, &id)?;
        let row = find(&session, &sha256)?;
        let bytes = read_original(&session, &row)?;
        Ok((row, bytes))
    })
    .await?;
    let mut res = bytes.into_response();
    secure(&mut res);
    let headers = res.headers_mut();
    // Never the real type: nothing may render it, even opened directly.
    headers.insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("application/octet-stream"),
    );
    if let Ok(v) = HeaderValue::from_str(&format!("attachment; filename=\"{}\"", file_name(&row))) {
        headers.insert(header::CONTENT_DISPOSITION, v);
    }
    Ok(res)
}

fn png_response(png: Vec<u8>) -> Response {
    let mut res = png.into_response();
    secure(&mut res);
    res.headers_mut()
        .insert(header::CONTENT_TYPE, HeaderValue::from_static("image/png"));
    res
}

/// A PNG rendition of `row` (`max_side` px), 404 when it has none.
fn render(session: &Session, row: &ObjectRow, max_side: u32) -> Result<Vec<u8>, ApiError> {
    if row.thumb == thumb::NONE || row.thumb == thumb::FAILED {
        return Err(ApiError::NotFound);
    }
    let original = read_original(session, row)?;
    thumbs::render(&original, max_side)
        .map(|r| r.png)
        .map_err(|_| ApiError::NotFound)
}

/// The stored thumbnail, if it is there and looks like the PNG we wrote.
fn stored_thumb(session: &Session, row: &ObjectRow) -> Option<Vec<u8>> {
    if row.thumb != thumb::READY {
        return None;
    }
    let path = session.thumb_path(&row.sha256)?;
    if std::fs::metadata(&path).ok()?.len() > MAX_THUMB_FILE {
        return None;
    }
    let png = std::fs::read(&path).ok()?;
    png.starts_with(b"\x89PNG\r\n\x1a\n").then_some(png)
}

async fn thumbnail(
    State(state): State<Arc<AppState>>,
    UrlPath((id, sha256)): UrlPath<(String, String)>,
) -> Result<Response, ApiError> {
    let id = parse_id(&id)?;
    let png = blocking(&state, move |s| {
        let (_, session) = open_ready(s, &id)?;
        let row = find(&session, &sha256)?;
        // Missing (import cancelled before the thumbnails, file removed): rendered now.
        match stored_thumb(&session, &row) {
            Some(png) => Ok(png),
            None => render(&session, &row, THUMB_SIZE),
        }
    })
    .await?;
    Ok(png_response(png))
}

async fn preview(
    State(state): State<Arc<AppState>>,
    UrlPath((id, sha256)): UrlPath<(String, String)>,
) -> Result<Response, ApiError> {
    let id = parse_id(&id)?;
    let png = blocking(&state, move |s| {
        let (_, session) = open_ready(s, &id)?;
        let row = find(&session, &sha256)?;
        render(&session, &row, PREVIEW_SIZE)
    })
    .await?;
    Ok(png_response(png))
}

